import type { Area } from "@/lib/types";

/**
 * Hover definitions (components/Glossary.tsx). One plain-words sentence or two, written for someone meeting the
 * word for the first time. `t` is how it is usually written (acronyms keep their case and only match that case),
 * `full` spells an acronym out, `alt` lists other spellings, `area` limits a meaning to one area.
 */
export type Gloss = { t: string; d: string; full?: string; alt?: string[]; area?: Area };

const g = (t: string, d: string, o: Partial<Omit<Gloss, "t" | "d">> = {}): Gloss => ({ t, d, ...o });
const hld = (t: string, d: string, o: Partial<Omit<Gloss, "t" | "d" | "area">> = {}): Gloss => ({ t, d, area: "hld", ...o });

